declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessTokenRef;

final class DcrInitialAccessTokenRefUnitTest extends TestCase
{
    public function test(): void
    {
        $uid = 'uid';
